"""WebKit + iPhone 15, customer, runner and owner apps on one device (shared storage, live updates, no reload).
Runner: choose pricing (nothing preselected), save own rates, pick a flat plan (none preselected, unchecked consent, logged), upgrade offer, downgrade, cancel, go available.
Customer: route choice (cheapest vs my order), book an errand, pick the runner, see the runner's upfront quote and job agreement, request.
Runner: sees details and pay before accepting, accepts, navigates, checks off each stop with photo and receipt, delivers.
Customer: live status, rate and tip. Owner: runner counts, subscription revenue and consent log. 0 console errors, 0 CSP."""
import re, sys, os
from playwright.sync_api import sync_playwright
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__))); from authseed import SEED
ROOT='http://localhost:8776/errand-beta-/'; OUT='/workspace/errand-tiles/screens/'
CFG=re.sub(r"(MAPS_API_KEY\s*=\s*)(['\"]).*?\2",r"\1''",open('/workspace/errand-tiles/js/config.js').read())
APPS={a: open(f'/workspace/errand-tiles/{a}/index.html').read().replace('; upgrade-insecure-requests','') for a in ['customer','runner','owner']}
PHOTO='/tmp/e2e_photo.jpg'
fails=[]; errs=[]; n=[0]
def check(c,m):
  n[0]+=1
  if not c: fails.append(m)
def ctx(b,p):
  c=b.new_context(**p.devices['iPhone 15']); c.add_init_script(SEED)
  c.add_init_script("window.__csp=0;document.addEventListener('securitypolicyviolation',e=>{window.__csp++;console.error('CSP '+e.violatedDirective)})")
  c.route('**/js/config.js*',lambda r: r.fulfill(content_type='text/javascript',body=CFG))
  for a,H in APPS.items(): c.route(ROOT+a+'/',(lambda H: lambda r: r.fulfill(content_type='text/html',body=H))(H))
  return c
def page(c,a):
  pg=c.new_page(); pg.on('console',lambda m: m.type=='error' and errs.append(a+' console: '+m.text)); pg.on('pageerror',lambda e: errs.append(f'{a} page: {e}'))
  pg.goto(ROOT+a+'/'); pg.wait_for_timeout(900); return pg
def photo(pg,sel):
  pg.set_input_files(sel,PHOTO); pg.wait_for_timeout(500)
if not os.path.exists(PHOTO):
  from PIL import Image; Image.new('RGB',(64,48),(200,180,120)).save(PHOTO)
with sync_playwright() as p:
  b=p.webkit.launch(); c=ctx(b,p)
  ru=page(c,'runner'); cu=page(c,'customer')
  W=lambda pg,ms=450: pg.wait_for_timeout(ms)
  T=lambda pg: pg.inner_text('body')
  check(ru.locator('#setupList').count()==1,'runner setup checklist shown')
  check(ru.locator('#onlineToggle').count()==0,'cannot go available before setup')
  ru.locator('#setupRates').tap(); W(ru)
  check(ru.evaluate("[...document.querySelectorAll('input[name=pricing]')].every(i=>!i.checked)"),'no pricing preselected')
  check(ru.locator('#rateFields').count()==0,'rate fields hidden until own rates chosen')
  ru.locator('#saveRates').tap(); W(ru,300); check(ru.evaluate("S.runners['test-runner'].pricing")==None,'save blocked without a choice')
  ru.locator('label[for=pr-own]').tap(); W(ru)
  check(ru.evaluate("[...document.querySelectorAll('#rateFields input')].every(i=>i.value==='')"),'rate fields start empty')
  check(ru.evaluate("[...document.querySelectorAll('#rateFields input')].every(i=>!/\\d/.test(i.placeholder))"),'no suggested numbers in rate placeholders')
  ru.fill('#rate-base','22'); ru.fill('#rate-extraStop','6'); ru.fill('#rate-lineHourly','30'); ru.fill('#rate-lineMin','1')
  ru.select_option('#areaSel','gnp'); ru.locator('#saveRates').tap(); W(ru)
  check(ru.evaluate("S.runners['test-runner'].pricing")=='own' and ru.evaluate("S.runners['test-runner'].rates.base")==22,'own rates saved')
  ru.locator('#setupPlan').tap(); W(ru)
  check('Placeholder pricing' in ru.inner_text('#planLabel'),'plan labeled Placeholder pricing')
  check('30 jobs or 6 weeks' in ru.inner_text('#planPilot'),'free pilot shown')
  tl=ru.inner_text('#tierList'); check('Starter' in tl and '$25.00/month' in tl and 'up to 15 jobs' in tl and 'Regular' in tl and '$75.00/month' in tl and '16 to 50 jobs' in tl and 'Pro' in tl and '$125.00/month' in tl and '51 or more jobs' in tl,'three flat plans listed')
  check(ru.evaluate("[...document.querySelectorAll('#tierList [role=radio]')].every(b=>b.getAttribute('aria-checked')==='false')"),'no plan preselected')
  check(ru.locator('#subPay').count()==0,'no Start button before a plan is picked')
  check(not re.search(r'boost|priority|featured|top placement|elite|rank higher|more visib|per 10 jobs|per block',T(ru),re.I),'no visibility perks or per-block billing on plan screen')
  ru.screenshot(path=OUT+'link_runner_plans.png')
  ru.locator('#tier-starter').tap(); W(ru); check(ru.get_attribute('#tier-starter','aria-checked')=='true','Starter picked')
  check(ru.locator('#subDisclosure').count()==1 and 'Never taken from your payouts' in ru.inner_text('#subDisclosure') and '30 jobs or 6 weeks' in ru.inner_text('#subDisclosure') and 'never charge you automatically' in ru.inner_text('#subDisclosure'),'disclosure next to Start')
  check(ru.locator('#subPay').is_disabled() and not ru.locator('#subConsent').is_checked(),'consent unchecked, Start disabled')
  ru.screenshot(path=OUT+'link_runner_plan.png')
  ru.locator('label[for=subConsent]').tap(); W(ru); check(not ru.locator('#subPay').is_disabled(),'Start enabled after consent')
  ru.locator('#subPay').tap(); W(ru)
  check(ru.locator('#subConfirm').count()==1,'on-screen plan confirmation'); ru.screenshot(path=OUT+'link_runner_subscribed.png')
  check(ru.evaluate("S.subLog.length")==1 and ru.evaluate("S.subLog[0].version")=='sub-v4' and ru.evaluate("S.subLog[0].tier")=='starter','consent logged with plan and version')
  check(ru.evaluate("planUsage(S.runners['test-runner'],Date.now()).inTrial")==True,'runner starts in the free pilot')
  ru.locator('#planDoneBtn').tap(); W(ru)
  ru.locator('#onlineToggle').tap(); W(ru); check(ru.evaluate("S.runners['test-runner'].online")==True,'runner available')
  cu.evaluate("S.prefs.home={addr:'10 Middle Neck Rd, Great Neck',lat:40.7905,lng:-73.7290}; S.stops=[mkStop('Groceries','stopshop',{items:[{n:'Milk',p:4,q:1}]}),mkStop('Post office',null,{custom:{name:'US Post Office',addr:'1 Welwyn Rd',lat:40.7998,lng:-73.7290,kind:'post'},items:[]})]; C.go('review')"); W(cu,800)
  cu.evaluate("S.c.runner=null; S.stops=[mkStop('Pharmacy','stopshop'),mkStop('Pharmacy','nsfarms'),mkStop('Pharmacy','cvs')]; R()"); W(cu,700)
  check(cu.locator('#route-cheap').count()==1 and cu.locator('#route-mine').count()==1,'two route options when orders differ')
  check(cu.get_attribute('#route-cheap','aria-checked')=='true','Cheapest route preselected')
  bc=cu.locator('#route-cheap').bounding_box(); bm=cu.locator('#route-mine').bounding_box()
  check(abs(bc['y']-bm['y'])<2 and bm['x']>bc['x']+bc['width']-1 and bm['x']+bm['width']<=394,'route options side by side on iPhone')
  check(re.search(r'\$\d',cu.inner_text('#route-cheap')) and re.search(r'\$\d',cu.inner_text('#route-mine')),'both route prices shown')
  cu.locator('#rk-test-runner').tap(); W(cu,500)
  check(cu.inner_text('#route-cheap').count('$')==1 and 'from' not in cu.inner_text('#ckRoute'),'prices are the picked runner\'s')
  cu.screenshot(path=OUT+'link_customer_route_choice.png')
  first=cu.evaluate("quote().route.order.map(i=>placeOf(S.stops[i]).name)")
  cu.locator('#route-mine').tap(); W(cu,500)
  check(cu.get_attribute('#route-mine','aria-checked')=='true' and cu.evaluate("quote().route.order.join()")=='0,1,2','My order selected')
  check('customer’s order): 1. Stop & Shop, 2. North Shore Farms, 3. CVS Pharmacy' in cu.text_content('#jobAgreement'),'agreement shows my order')
  check(cu.evaluate("[...document.querySelectorAll('.rlist .sub')].map(e=>e.textContent)")==['Stop & Shop','North Shore Farms','CVS Pharmacy'],'review list in my order')
  cu.locator('#route-cheap').tap(); W(cu,500)
  check(cu.evaluate("[...document.querySelectorAll('.rlist .sub')].map(e=>e.textContent)")==first,'review list in cheapest order')
  check(cu.evaluate("quote().route.order.map(i=>placeOf(S.stops[i]).name)")==first and ', '.join(f'{i+1}. {x}' for i,x in enumerate(first)) in cu.text_content('#jobAgreement'),'back to cheapest; agreement shows that order')
  cu.evaluate("S.c.runner=null; S.c.route=null; S.stops=[mkStop('Pharmacy','cvs')]; R()"); W(cu,500)
  check(cu.locator('#route-mine').count()==0 and cu.locator('#route-cheap').count()==0,'single stop: no route choice')
  cu.evaluate("S.stops=[mkStop('Groceries','stopshop',{items:[{n:'Milk',p:4,q:1}]}),mkStop('Post office',null,{custom:{name:'US Post Office',addr:'1 Welwyn Rd',lat:40.7998,lng:-73.7290,kind:'post'},items:[]})]; R()"); W(cu,700)
  check(cu.locator('#route-cheap').count()==1 or cu.locator('#routeSame').count()==1,'route section shown for the errand')
  check(cu.locator('#rk-test-runner').count()==1,'customer sees the runner to pick')
  check(cu.locator('#payBtn').is_disabled(),'no auto-assign: Request disabled until a runner is picked')
  check(cu.evaluate("S.c.runner||null")==None,'no runner preselected')
  check('Final drop-off' in T(cu),'final drop-off label on review')
  cu.locator('#rk-test-runner').tap(); W(cu,600)
  check('$22.00' in cu.inner_text('#ckPrice'),'runner own-rate quote shown: '+cu.inner_text('#ckPrice')[:80])
  check(cu.locator('#jobAgreement').count()==1,'job agreement shown at booking')
  check('Add a test card' in cu.inner_text('#payBtn'),'main button adds a test card first'); cu.locator('#payBtn').tap(); W(cu,600); check(cu.evaluate("!!S.pay.method") and cu.evaluate("S.trip") is None,'test card added inline, nothing booked yet')
  check(cu.locator('#ckConsent').count()==1 and not cu.locator('#ckConsent').is_checked(),'checkout consent box present and unchecked')
  check(cu.locator('#payBtn').is_disabled(),'Request disabled until consent'); check('Demo only' in T(cu),'Demo only next to Request')
  cu.locator('label[for=ckConsent]').tap(); W(cu,300); check(not cu.locator('#payBtn').is_disabled(),'Request enabled after consent')
  cu.locator('#payBtn').tap(); W(cu,800)
  check(cu.evaluate("!!(S.trip&&S.trip.consent&&S.trip.consent.at)"),'checkout consent logged on the order')
  check(cu.evaluate("S.trip&&S.trip.status")=='matching','trip requested')
  check(cu.evaluate("S.trip.runner")=='test-runner','trip goes only to the picked runner')
  W(ru,600)
  check(ru.locator('#offerCard').count()==1,'runner sees request details')
  check('$22.00' in ru.inner_text('#offerCard') and 'Final drop-off' in ru.inner_text('#offerCard'),'runner sees pay and drop-off before accepting')
  check(ru.locator('#offerCard #jobAgreement').count()==1,'job agreement shown at accept')
  check(ru.locator('#counterBtn').count()==1 and ru.locator('#declineTrip').count()==1,'runner can change price or decline')
  ru.screenshot(path=OUT+'link_runner_request.png')
  ru.locator('#acceptTrip').tap(); W(ru); W(cu,300)
  check(cu.evaluate("S.trip.status")=='accepted','customer live accepted')
  check(ru.locator('#navBtn').count()==1 and ru.get_attribute('#navBtn','href').startswith('https://maps.apple.com/'),'Navigate opens Maps')
  for k in range(2):
    ru.locator('#arriveBtn').tap(); W(ru)
    photo(ru,'#ph-photo')
    if ru.locator('#ph-receipt').count(): photo(ru,'#ph-receipt'); ru.fill('#rcptTotal','4.29')
    ru.locator('#completeStop').tap(); W(ru)
  check(cu.evaluate("S.trip.step")==2,'both stops checked off: step '+str(cu.evaluate("S.trip.step")))
  ru.locator('#deliverBtn').tap(); W(ru,300); check(cu.evaluate("S.trip.status")=='accepted','deliver blocked without photo')
  photo(ru,'#ph-deliver'); ru.locator('#deliverBtn').tap(); W(ru,700)
  check(cu.evaluate("S.trip&&S.trip.status")=='delivered','customer live delivered')
  check(ru.evaluate("S.runners['test-runner'].earn.length")==1 and 'Weekly payout, free'==ru.evaluate("S.runners['test-runner'].earn[0].payout"),'earnings go to the free weekly payout')
  check(ru.evaluate("S.runners['test-runner'].earn[0].price")==22,'runner keeps full price (no platform cut)')
  cu.evaluate("C.go('tracking')"); W(cu,600)
  if cu.locator('#star5').count()==0 and cu.locator('#rateBtn').count(): cu.locator('#rateBtn').tap(); W(cu)
  check(cu.locator('#star5').count()==1,'rating screen'); cu.locator('#star5').tap(); W(cu,300); cu.locator('#tip5').tap(); W(cu,300)
  cu.screenshot(path=OUT+'link_customer_rate.png'); cu.locator('#submitRating').tap(); W(cu,700)
  check(cu.evaluate("S.history.length")==1,'order in history')
  check(ru.evaluate("S.runners['test-runner'].rating")==[5,1],'rating recorded '+str(ru.evaluate("S.runners['test-runner'].rating")))
  check(ru.evaluate("S.runners['test-runner'].earn[0].tip")==5,'tip goes to runner')
  ow=page(c,'owner')
  check(ow.inner_text('#owKpis').split()[2]=='1','owner: 1 runner registered')
  op=ow.inner_text('#owPlans'); check('Placeholder pricing' in T(ow) and 'Free pilot' in op and 'Starter' in op and 'Regular' in op and 'Pro' in op,'owner: plans panel, runner in free pilot')
  check(not re.search(r'/mo\b',T(ow)),'owner: no old monthly tier prices')
  check(not re.search(r'order revenue|gross bookings|runner pay|schedule|shift',T(ow),re.I),'owner: no order revenue, pay or schedule controls')
  ow.screenshot(path=OUT+'link_owner_overview.png')
  ow.locator('.mobile-owner-tabs button',has_text='Subscriptions').tap(); W(ow); check('Consent log' in T(ow),'owner: consent log')
  ow.locator('.mobile-owner-tabs button',has_text='Runners').tap(); W(ow)
  ow.locator('#owDeact-test-runner').tap(); W(ow,300); check(ow.evaluate("S.runners['test-runner'].deactivated")==None,'deactivation needs a reason')
  check(ow.evaluate("[...document.querySelectorAll('#owWhy-test-runner option')].map(o=>o.value).filter(Boolean)")==['Safety','Fraud','Illegal acts','Unpaid subscription'],'deactivation reasons limited')
  ru.locator('#onlineToggle').tap(); W(ru); check(ru.evaluate("S.runners['test-runner'].online")==False,'runner can go offline freely')
  ru.evaluate("const r=S.runners['test-runner'];r.trialFrom=Date.now()-50*864e5;r.sub.since=r.trialFrom;r.jobLog=Array.from({length:30},(_,i)=>r.trialFrom+i*1000).concat(Array.from({length:16},(_,i)=>Date.now()-i*60000));Store.save();RN.sc('');RN.tab('drive')"); W(ru,500)
  check(ru.locator('#upgradeNudge').count()==1,'over the limit: optional upgrade shown on the home tab')
  n0=ru.evaluate("S.subLog.length"); ru.locator('#upgradeNudge .cell').tap(); W(ru)
  check(ru.locator('#upgradeOffer').count()==1 and 'Regular' in ru.inner_text('#upgradeOffer') and 'unless you accept' in ru.inner_text('#upgradeOffer'),'upgrade offer with accept or decline')
  check(ru.evaluate("planUsage(S.runners['test-runner']).due")==25 and ru.evaluate("S.runners['test-runner'].sub.tier")=='starter','no automatic charge or plan change when over')
  ru.screenshot(path=OUT+'link_runner_upgrade_offer.png')
  ru.locator('#upgradeNo').tap(); W(ru)
  check(ru.locator('#upgradeOffer').count()==0 and ru.evaluate("S.runners['test-runner'].sub.tier")=='starter' and ru.evaluate("S.subLog.length")==n0,'decline keeps Starter, nothing logged or billed')
  ru.evaluate("S.runners['test-runner'].sub.declined=null;R()"); W(ru); ru.locator('#upgradeYes').tap(); W(ru)
  check(ru.evaluate("S.runners['test-runner'].sub.tier")=='regular' and ru.evaluate("S.subLog[0].action")=='upgrade' and ru.evaluate("S.subLog[0].from")=='Starter','accepted upgrade switches to Regular and is logged')
  ru.locator('#tier-starter').tap(); W(ru); check(ru.locator('#changeConfirm').count()==1 and 'Starter' in ru.inner_text('#changeConfirm'),'downgrade asks to confirm')
  ru.locator('#changeYes').tap(); W(ru); check(ru.evaluate("S.runners['test-runner'].sub.tier")=='starter' and ru.evaluate("S.subLog[0].action")=='downgrade','downgrade anytime, logged')
  ru.locator('#cancelPlan').tap(); W(ru); ru.locator('#cancelYes').tap(); W(ru); check(ru.evaluate("S.runners['test-runner'].sub.status")=='cancelled' and ru.evaluate("planUsage(S.runners['test-runner']).due")==0,'cancel anytime, nothing due')
  ru.evaluate("const r=S.runners['test-runner'];r.sub={tier:'pro',status:'active',since:Date.now()-50*864e5,consent:{}};r.since=Date.now()-50*864e5;r.cashouts=[];r.earn.forEach(x=>x.paid=false);RN.sc('plan')"); W(ru)
  check(ru.inner_text('#perk-pro')=='Pro plan includes 2 free instant cash-outs a month (eligibility applies). Weekly payouts are always free.','exact Pro wording')
  check(all(ru.inner_text('#perk-'+k)=='Weekly payouts are always free.' for k in ('starter','regular')),'weekly payouts free shown on every plan')
  check('at least 14 days active and no unresolved chargebacks' in ru.inner_text('#planTerms') and 'Never tied to ratings, acceptance or hours' in ru.inner_text('#planTerms'),'eligibility note in plan terms')
  ru.screenshot(path=OUT+'link_runner_pro_plan.png')
  ru.evaluate("RN.sc('');RN.tab('earn')"); W(ru)
  check(ru.inner_text('#cashCount')=='2 of 2 free instant cash-outs left' and not ru.locator('#cashOutBtn').is_disabled(),'Pro: 2 of 2 free cash-outs, button enabled')
  check('Weekly payout · free' in ru.inner_text('#weeklyCell'),'weekly payout shown as free')
  ru.screenshot(path=OUT+'link_runner_cashout.png')
  ru.locator('#cashOutBtn').tap(); W(ru); check(ru.evaluate("S.runners['test-runner'].earn.every(x=>x.paid)") and ru.inner_text('#cashCount')=='1 of 2 free instant cash-outs left','cash-out uses one free cash-out')
  ru.evaluate("const r=S.runners['test-runner'];r.earn.forEach(x=>x.paid=false);R()"); W(ru); ru.locator('#cashOutBtn').tap(); W(ru)
  ru.evaluate("S.runners['test-runner'].earn.forEach(x=>x.paid=false);R()"); W(ru)
  check(ru.inner_text('#cashCount')=='0 of 2 free instant cash-outs left' and ru.locator('#cashOutBtn').is_disabled() and 'unavailable until' in ru.inner_text('#cashWhy'),'after 2: unavailable until next month')
  check(not re.search(r'fee to cash|pay \$|for a fee|instant fee|%',ru.inner_text('#cashCell'),re.I),'no paid instant option and no percentages')
  ru.screenshot(path=OUT+'link_runner_cashout_used.png')
  check(not re.search(r'\d\s?%|percent',T(ru),re.I),'no percentages on the runner earnings screen')
  for pg in (cu,ru,ow): check(pg.evaluate('window.__csp')==0,'CSP violations')
  check(cu.evaluate("performance.getEntriesByType('navigation')[0].type")!='reload','customer did not reload')
  b.close()
fails+=errs
print(f'{n[0]-len([f for f in fails if f not in errs])}/{n[0]} checks passed'); [print('FAIL',f) for f in fails]
sys.exit(1 if fails else 0)
